import json
from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message


STATUS_LABEL = {"red": "MERAH", "yellow": "KUNING (WASPADA)", "green": "HIJAU (AMAN)", "unknown": "TIDAK DIKETAHUI (periksa data)"}


class MBGFlowCSummary(Component):
    display_name = "Flow C - Daily Summary"
    description = (
        "Summarizes structured Flow B signals for a selected period. "
        "No LLM and no hardcoded demo data."
    )
    icon = "clipboard-list"
    name = "MBGFlowCSummary"

    inputs = [
        MessageTextInput(
            name="input_data",
            display_name="Flow B Structured Results JSON",
            required=True,
            input_types=["Message"],
        )
    ]

    outputs = [
        Output(display_name="Summary Result", name="result", method="make_result"),
        Output(display_name="Structured Summary", name="structured", method="make_data"),
    ]

    def _raw_text(self):
        raw = getattr(self.input_data, "text", self.input_data)
        return str(raw).strip()

    def _parse(self):
        raw = self._raw_text()
        try:
            data = json.loads(raw)
        except Exception as e:
            raise ValueError(
                "Flow C expects the structured JSON output of Flow B. "
                "Do not paste the human-readable Flow B display text."
            ) from e

        self._warnings = []
        if isinstance(data, dict):
            self._warnings = [str(w) for w in (data.get("warnings") or [])]
            schools = data.get("schools")
        elif isinstance(data, list):
            schools = data
        else:
            schools = None

        if not isinstance(schools, list):
            raise ValueError('Invalid Flow B structure. Expected {"schools": [...]}.')
        return schools

    def _summarize(self):
        schools = self._parse()
        counts = {"red": 0, "yellow": 0, "green": 0, "unknown": 0}
        review = []
        summary_schools = []
        warnings = list(self._warnings)
        if not schools:
            warnings.append("Tidak ada data sekolah pada input")

        for item in schools:
            if not isinstance(item, dict):
                warnings.append("Ada item sekolah yang bentuknya tidak valid dan dilewati")
                continue
            school_name = str(item.get("school_name") or item.get("school_id") or "Unknown school")
            # status hilang / tidak dikenal TIDAK boleh jadi hijau: tandai "unknown" dan perlu ditinjau
            status = str(item.get("status", "")).lower().strip()
            if status not in ("red", "yellow", "green"):
                status = "unknown"
            counts[status] += 1

            evidence = item.get("evidence", [])
            if not isinstance(evidence, list):
                evidence = []
            evidence = [str(x) for x in evidence if str(x).strip()]

            sc = item.get("severity_counts") or {"tinggi": 0, "sedang": 0, "rendah": 0}
            needs_review = status in ("red", "yellow", "unknown")
            if needs_review:
                review.append(school_name)

            summary_schools.append({
                "school_id": item.get("school_id", ""),
                "school_name": school_name,
                "status": status,
                "severity_counts": sc,
                "highlight": item.get("highlight"),
                "needs_review": needs_review,
                "main_signals": evidence,
                "last_updated": item.get("last_updated", "(belum ada)"),
            })

        return {
            "total_schools": len(summary_schools),
            "schools_needing_review": review,
            "status_counts": counts,
            "warnings": warnings,
            "schools": summary_schools,
        }

    def make_data(self) -> Data:
        try:
            return Data(data=self._summarize())
        except Exception as e:
            self.status = f"Error: {e}"
            return Data(data={"error": str(e)})

    def make_result(self) -> Message:
        try:
            summary = self._summarize()
            counts = summary["status_counts"]
            review = summary["schools_needing_review"]

            lines = [
                "MBG Guard - Flow C Daily Summary",
                "",
                f"Total sekolah: {summary['total_schools']}",
                f"Perlu ditinjau: {len(review)}",
                f"Status: MERAH {counts['red']} | KUNING {counts['yellow']} | HIJAU {counts['green']}"
                + (f" | TIDAK DIKETAHUI {counts['unknown']}" if counts["unknown"] else ""),
                "",
            ]
            for w in summary["warnings"]:
                lines.append(f"PERINGATAN DATA: {w}")
            if summary["warnings"]:
                lines.append("")

            for school in summary["schools"]:
                sc = school["severity_counts"]
                label = STATUS_LABEL.get(school["status"], school["status"].upper())
                komposisi = f"{sc.get('tinggi', 0)} tinggi, {sc.get('sedang', 0)} sedang, {sc.get('rendah', 0)} rendah"

                lines.append(f"{school['school_name']} — risiko keseluruhan {label}")
                lines.append(f"- Terdiri dari: {komposisi}")
                if school["highlight"]:
                    lines.append(f"- Sorotan keluhan: {school['highlight']}")
                for signal in school["main_signals"]:
                    lines.append(f"- {signal}")
                lines.append(f"- Pembaruan terakhir: {school['last_updated']}")
                lines.append("")

            text = "\n".join(lines).strip()
            self.status = text
            return Message(text=text)
        except Exception as e:
            self.status = f"Error: {e}"
            return Message(text=f"Flow C error: {e}")
